const data = $input.first().json;
const answers = data.form_response?.answers || [];
const definition = data.form_response?.definition?.fields || [];

function getAnswer(titleContains) {
  const field = definition.find(f => f.title?.toLowerCase().includes(titleContains.toLowerCase()));
  if (!field) return 'N/A';
  const answer = answers.find(a => a.field?.id === field.id);
  if (!answer) return 'N/A';
  if (answer.type === 'text') return answer.text || 'N/A';
  if (answer.type === 'email') return answer.email || 'N/A';
  if (answer.type === 'phone_number') return answer.phone_number || 'N/A';
  if (answer.type === 'number') return answer.number?.toString() || 'N/A';
  if (answer.type === 'boolean') return answer.boolean ? 'Yes' : 'No';
  if (answer.type === 'choice') return answer.choice?.label || 'N/A';
  if (answer.type === 'choices') return answer.choices?.labels?.join(', ') || 'N/A';
  return 'N/A';
}

// Match actual Typeform field titles
const name = getAnswer('full name');
const email = getAnswer('email address');
const gender = getAnswer('gender');
const instagram = getAnswer('instagram handle');
const work = getAnswer('do for work');
const challenge = getAnswer('biggest challenge');
const goal12weeks = getAnswer('number 1 goal');
const vision12months = getAnswer('12 months from now');
const phone = getAnswer('add in your number');

const message = `🚀 *NEW LEAD*\n━━━━━━━━━━━━━━━━━━\n\n👤 *${name}*\n\n📧 Email: ${email}\n📱 Phone: ${phone}\n📸 Instagram: ${instagram !== 'N/A' ? '@' + instagram.replace('@', '') : 'N/A'}\n⚧ Gender: ${gender}\n\n💼 *Work*: ${work}\n\n🎯 *Biggest Challenge*\n${challenge}\n\n🏆 *12-Week Goal*\n${goal12weeks}\n\n🔮 *12-Month Vision*\n${vision12months}\n\n━━━━━━━━━━━━━━━━━━\n⏰ Follow up ASAP!`;

return [{ json: { message, clientName: name } }];
